{
  "гриб": "Лимонный мухомор (Amanita citrina)",
  "состав": [
    {
      "вещество": "α-аматин (α-amanitin)",
      "содержание": "≈ 1–2 мг/100 г свежего веса (капилляры, кольцо, ножка)",
      "влияние": "Блокирует РНК-полимеразу II, вызывая гибель клеток печени и почек при пероральном отравлении."
    },
    {
      "вещество": "β-аматин (β-amanitin)",
      "содержание": "≈ 0,1–0,5 мг/100 г свежего веса",
      "влияние": "Ингибирует РНК-полимеразу II с меньшей эффективностью, чем α-аматин; вносит вклад в гепато- и нефротоксичность."
    },
    {
      "вещество": "γ-аматин (γ-amanitin)",
      "содержание": "следовые количества, < 0,1 мг/100 г",
      "влияние": "Слабый ингибитор РНК-полимеразы II; при обычной дозе практически не даёт выраженного клинического эффекта."
    },
    {
      "вещество": "Виоротоксин (virotoxin)",
      "содержание": "≈ 0,5–1 мг/100 г свежего веса",
      "влияние": "Связывается с РНК-полимеразой II, токсичность ниже аматоксинов; усиливает общую гепатотропность."
    },
    {
      "вещество": "α-фаллацидин (α-fallacidine)",
      "содержание": "≈ 0,5–1 мг/100 г (преимущественно в ножке)",
      "влияние": "Активает ионные каналы мембран эритроцитов, вызывая гемолиз и нарушение водно-солевого обмена."
    },
    {
      "вещество": "β-фаллоидин (β-falloidin)",
      "содержание": "≈ 0,2–0,5 мг/100 г (ножка)",
      "влияние": "Мембраноактивное соединение, способное вызвать лизис эритроцитов при попадании в кровь."
    },
    {
      "вещество": "Эргостерол",
      "содержание": "≈ 1–3 % от сухого веса",
      "влияние": "Стерол, предшественник витамина D₂; сам по себе нетоксичен и участвует в метаболизме липидов."
    },
    {
      "вещество": "Хиро-инозитол",
      "содержание": "≈ 1–2 % от сухого веса (несколько мг/г)",
      "влияние": "Осмотически активный осмолит; при высокой дозе может усиливать диурез и потерю электролитов."
    },
    {
      "вещество": "β-Глюканы (полисахариды)",
      "содержание": "≈ 5–10 % от сухого веса",
      "влияние": "Структурный полимер клеточной стенки; нетоксичен, может оказывать умеренное иммуномодулирующее действие."
    },
    {
      "вещество": "Тритерпены (аманитол, мусколон и др.)",
      "содержание": "≈ 0,3–1 % от сухого веса",
      "влияние": "Легкие летучие соединения с характерным запахом; при обычных дозах клинически значимого действия не оказывают."
    }
  ]
}

{
  "гриб": "Цезарский гриб (Amanita caesarea)",
  "состав": [
    {
      "вещество": "Мусцимол",
      "содержание": "0,1–0,5 % от сухого веса",
      "влияние": "Агонист ГАМК-рецепторов, в малых дозах оказывает лёгкое седативное действие."
    },
    {
      "вещество": "Иботеновая кислота",
      "содержание": "0,05–0,2 % от сухого веса",
      "влияние": "Агонист глутаматных (NMDA) рецепторов, при избытке вызывает возбуждение и спутанность сознания."
    },
    {
      "вещество": "Гигрозин",
      "содержание": "0,1–0,3 % от сухого веса",
      "влияние": "Специфический психоактивный амин циклопропанолового ряда, придаёт грибу мягкое гипнотическое свойство."
    },
    {
      "вещество": "Белки (аминокислоты)",
      "содержание": "3–5 % от свежего веса",
      "влияние": "Обеспечивают питательную ценность; богаты глутаминовой и аспарагиновой кислотами, ответственными за вкусовые свойства."
    },
    {
      "вещество": "Хитин",
      "содержание": "5–10 % от сухого веса",
      "влияние": "Структурный полисахарид клеточных стенок, не усваивается человеком, при избытке может затруднять пищеварение."
    },
    {
      "вещество": "Полисахариды (гликоген, маннит, арабиноза)",
      "содержание": "10–20 % от сухого веса",
      "влияние": "Служат источником энергии; гликоген при переваривании частично расщепляется до глюкозы."
    },
    {
      "вещество": "Минеральные соли (K, P, Na, Ca, Mg)",
      "содержание": "3–5 % от сухого веса (зола)",
      "влияние": "Поддерживают электролитный баланс и участвуют в ферментативных реакциях организма."
    },
    {
      "вещество": "Витамины группы B (тиамин, рибофлавин, ниацин)",
      "содержание": "неизвестно (следы, мкг/г)",
      "влияние": "Участвуют в метаболизме углеводов, белков и жиров, поддерживают работу нервной системы."
    }
  ]
}

{
  "гриб": "Мухомор вонючий (Amanita virosa)",
  "состав": [
    {
      "вещество": "α-Аманицин (alpha-amanitin)",
      "содержание": "0,02–0,05 % от свежего веса",
      "влияние": "Сильно ингибирует РНК-полимеразу II, останавливая синтез мРНК и вызывая некроз клеток печени и почек."
    },
    {
      "вещество": "β-Аманицин (beta-amanitin)",
      "содержание": "0,01–0,03 % от свежего веса",
      "влияние": "Подавляет РНК-полимеразы I и III, нарушая синтез рРНК и тРНК в клетках."
    },
    {
      "вещество": "γ-Аманицин (gamma-amanitin)",
      "содержание": "0,001–0,01 % от свежего веса",
      "влияние": "Ингибирует РНК-полимеразу I, ослабляя синтез прекурсоров рибосомальных РНК."
    },
    {
      "вещество": "Эпиманин (epimanin)",
      "содержание": "0,005–0,01 % от свежего веса",
      "влияние": "По механизму действия аналогичен β-аманицину — блокирует РНК-полимеразы I и III."
    },
    {
      "вещество": "А-манин (a-mannin)",
      "содержание": "0,005–0,01 % от свежего веса",
      "влияние": "Менее токсичный циклический пептид, слабо ингибирующий РНК-полимеразы; способствует осмотическому набуханию клеток."
    },
    {
      "вещество": "Маитотоксин (maitotoxin)",
      "содержание": "0,01–0,05 % от сухого веса",
      "влияние": "Стероидное сапониноподобное соединение, нарушающее ионные каналы и проницаемость клеточных мембран, ведёт к гибели нейронов и эпителиальных клеток."
    },
    {
      "вещество": "Вириозин (virosin)",
      "содержание": "0,5–2 % от сухого веса",
      "влияние": "Белок-лектин и ингибитор α-маннозидазы, нарушающий клеточное узнавание и функцию печени; специфичен для Amanita virosa."
    }
  ]
}
